<?php
/** TEMP PS S1685 mo — DEPLOY šablono pataisa (dvigubas taškas); token_get_all, heartbeat. */
add_action('init', function(){
  if (!isset($_GET['ps_s1685mo'])) return; $o=array('v'=>'S1685 mo'); $t=WPMU_PLUGIN_DIR.'/ps-sablonai/refill-pakartoti.php'; $nt=base64_decode(''); if(md5($nt)!=='e2a0f2387b49b4e5e56fac5abed8f786'){ $o['STOP']='md5'; echo json_encode($o); exit; }
  try { token_get_all($nt, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']=$e->getMessage(); echo json_encode($o); exit; }
  file_put_contents($t,$nt); if(function_exists('opcache_invalidate')) opcache_invalidate($t,true); $o['md5']=md5_file($t);
  $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $o['heartbeat']=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb);
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o); exit;
});
